/* Internal storage primitives. A span descriptor stays at a fixed address
 * while it occupies a front; the caller destroys its contents before release. */
typedef enum { GROWTH_LOW, GROWTH_HIGH } GrowthFront;
typedef struct GrowthSpan GrowthSpan;
typedef struct {
    Source mapping;
    size_t low, high;
    GrowthSpan *fronts[2];
} GrowthStack;
struct GrowthSpan {
    GrowthStack *stack;
    GrowthFront front;
    size_t saved_cursor, element_size;
};

static GrowthStack growth_stack(size_t capacity) {
    return (GrowthStack){.mapping = source_stack(capacity), .high = capacity};
}

static int growth_open(GrowthStack *stack, GrowthSpan *span, GrowthFront front,
                       size_t element_size, size_t alignment) {
    if (stack->mapping.capacity == 0 || (front != GROWTH_LOW && front != GROWTH_HIGH) ||
            stack->fronts[front] || span->stack) return 0;
    if (alignment == 0 || (alignment & (alignment - 1)) || element_size == 0 ||
            element_size % alignment != 0 || (uintptr_t)stack->mapping.base % alignment != 0)
        return 0;
    size_t saved = front == GROWTH_LOW ? stack->low : stack->high;
    size_t residue = saved & (alignment - 1);
    size_t padding = front == GROWTH_LOW && residue ? alignment - residue : residue;
    if (padding > stack->high - stack->low) return 0;
    if (front == GROWTH_LOW) stack->low += padding;
    else stack->high -= padding;
    *span = (GrowthSpan){stack, front, saved, element_size};
    stack->fronts[front] = span;
    return 1;
}

static unsigned char *growth_extend(GrowthSpan *span, size_t count) {
    GrowthStack *stack = span->stack;
    if (!stack || stack->fronts[span->front] != span) return NULL;
    size_t available = stack->high - stack->low;
    if (count > available / span->element_size) return NULL;
    size_t bytes = count * span->element_size;
    if (span->front == GROWTH_LOW) {
        size_t offset = stack->low;
        stack->low += bytes;
        return stack->mapping.base + offset;
    }
    stack->high -= bytes;
    return stack->mapping.base + stack->high;
}

static void growth_release(GrowthSpan *span) {
    GrowthStack *stack = span->stack;
    if (!stack || stack->fronts[span->front] != span) fail("front de croissance inactif");
    if (span->front == GROWTH_LOW) stack->low = span->saved_cursor;
    else stack->high = span->saved_cursor;
    stack->fronts[span->front] = NULL;
    *span = (GrowthSpan){0};
}

static void growth_close(GrowthStack *stack) {
    if (stack->fronts[GROWTH_LOW] || stack->fronts[GROWTH_HIGH])
        fail("data stack avec un front encore vivant");
    source_close(&stack->mapping);
    *stack = (GrowthStack){0};
}

typedef struct {
    GrowthSpan span;
    GrowthStack dedicated;
} GrowthSpanPlacement;

static int growth_place(GrowthSpanPlacement *placement, GrowthStack *preferred,
                        size_t dedicated_capacity, size_t element_size, size_t alignment) {
    if (placement->span.stack || alignment == 0 || (alignment & (alignment - 1)) ||
            element_size == 0 || element_size % alignment) return 0;
    if (preferred) {
        for (GrowthFront front = GROWTH_LOW; front <= GROWTH_HIGH; ++front) {
            if (growth_open(preferred, &placement->span, front, element_size, alignment)) {
                if (element_size <= preferred->high - preferred->low) return 1;
                growth_release(&placement->span);
            }
        }
    }
    if (dedicated_capacity < element_size) return 0;
    placement->dedicated = growth_stack(dedicated_capacity);
    if (growth_open(&placement->dedicated, &placement->span, GROWTH_LOW, element_size, alignment))
        return 1;
    growth_close(&placement->dedicated);
    return 0;
}

static void growth_unplace(GrowthSpanPlacement *placement) {
    growth_release(&placement->span);
    if (placement->dedicated.mapping.capacity) growth_close(&placement->dedicated);
}

typedef struct GrowthRegion GrowthRegion;
typedef struct {
    Source slots;
    size_t region_size, payload_offset;
} GrowthRegionPool;
struct GrowthRegion {
    GrowthRegionPool *pool;
    Cell *slot;
    size_t used, element_size;
};

static size_t growth_region_stride(size_t region_size, size_t *payload_offset) {
    const size_t alignment = _Alignof(max_align_t);
    size_t header = sizeof(Cell) + sizeof(GrowthRegion *);
    size_t offset = (header + alignment - 1) / alignment * alignment;
    if (region_size == 0 || region_size > SIZE_MAX - offset - (alignment - 1))
        fail("taille de région invalide");
    *payload_offset = offset;
    return (offset + region_size + alignment - 1) / alignment * alignment;
}

static GrowthRegionPool growth_region_pool(size_t slots, size_t region_size) {
    size_t offset;
    size_t stride = growth_region_stride(region_size, &offset);
    Source source = source_pool_layout(slots, stride - sizeof(Cell));
    if ((uintptr_t)source.base % _Alignof(max_align_t) || source.stride % _Alignof(max_align_t))
        fail("alignement de région non pris en charge");
    return (GrowthRegionPool){source, region_size, offset};
}

static void growth_region_set_holder(Cell *slot, GrowthRegion *holder) {
    memcpy((unsigned char *)slot + sizeof(Cell), &holder, sizeof holder);
}

static int growth_region_is_live(GrowthRegion *region) {
    if (!region->slot || !region->pool || region->pool->region_size == 0) return 0;
    Source *source = &region->pool->slots;
    uintptr_t offset = (uintptr_t)region->slot - (uintptr_t)source->base;
    if (offset >= source->used || offset % source->stride || !region->slot->alive) return 0;
    GrowthRegion *holder;
    memcpy(&holder, (unsigned char *)region->slot + sizeof(Cell), sizeof holder);
    return holder == region;
}

static int growth_region_open(GrowthRegionPool *pool, GrowthRegion *region,
                              size_t element_size, size_t alignment) {
    if (region->slot || pool->region_size == 0 || element_size == 0 || alignment == 0 ||
            _Alignof(max_align_t) % alignment || element_size % alignment) return 0;
    Cell *slot = cell_try_new(&pool->slots, 0, NULL);
    if (!slot) return 0;
    *region = (GrowthRegion){pool, slot, 0, element_size};
    growth_region_set_holder(slot, region);
    return 1;
}

static unsigned char *growth_region_extend(GrowthRegion *region, size_t count) {
    if (!growth_region_is_live(region)) return NULL;
    size_t available = region->pool->region_size - region->used;
    if (count > available / region->element_size) return NULL;
    unsigned char *block = (unsigned char *)region->slot + region->pool->payload_offset + region->used;
    region->used += count * region->element_size;
    return block;
}

static void growth_region_release(GrowthRegion *region) {
    if (!growth_region_is_live(region)) fail("région de croissance inactive");
    growth_region_set_holder(region->slot, NULL);
    cell_drop(region->slot);
    *region = (GrowthRegion){0};
}

static void growth_region_pool_close(GrowthRegionPool *pool) {
    if (pool->slots.mapping_size) source_close(&pool->slots);
    else source_check_empty(&pool->slots);
    *pool = (GrowthRegionPool){0};
}

/* The placement descriptor owns its dedicated pool, when one is needed. */
typedef struct {
    GrowthRegion region;
    GrowthRegionPool dedicated;
} GrowthRegionPlacement;

static int growth_region_place(GrowthRegionPlacement *placement, GrowthRegionPool *preferred,
                               size_t region_size, size_t element_size, size_t alignment) {
    if (placement->region.slot || region_size == 0 || element_size == 0 || alignment == 0 ||
            _Alignof(max_align_t) % alignment || element_size % alignment) return 0;
    if (preferred && preferred->region_size == region_size &&
            growth_region_open(preferred, &placement->region, element_size, alignment)) return 1;
    placement->dedicated = growth_region_pool(1, region_size);
    if (!growth_region_open(&placement->dedicated, &placement->region, element_size, alignment))
        fail("impossible d’ouvrir une région dédiée");
    return 1;
}

static void growth_region_unplace(GrowthRegionPlacement *placement) {
    growth_region_release(&placement->region);
    if (placement->dedicated.region_size) growth_region_pool_close(&placement->dedicated);
}

struct VectorStorage {
    GrowthStack stack;
    Source region_classes;
    size_t slots, class_count;
};

enum { VECTOR_STACK_CAPACITY = 4 * 1024 * 1024 };
enum { VECTOR_STORAGE_UNRESERVED, VECTOR_REGION_RESERVED, VECTOR_FRONT_RESERVED, VECTOR_DEDICATED_RESERVED };

typedef struct {
    GrowthSpanPlacement span;
    GrowthRegionPlacement region;
    size_t length, element_size;
    int owns_handles;
} VectorItems;

_Static_assert(_Alignof(VectorItems) <= _Alignof(Cell),
               "Vector descriptors require aligned slots");

static Source source_vector_pool(size_t count, VectorStorage *storage) {
    Source source = source_pool_layout(count, sizeof(VectorItems));
    storage->slots = count;
    source.vectors = storage;
    return source;
}

static VectorItems *vector_items(Cell *cell) {
    return (VectorItems *)((unsigned char *)cell + sizeof(Cell));
}

static void vector_refresh_front_boundary(VectorStorage *storage) {
    GrowthStack *stack = &storage->stack;
    if (stack->fronts[GROWTH_HIGH]) return;
    const GrowthRegionPool *classes = (const GrowthRegionPool *)storage->region_classes.base;
    stack->high = stack->mapping.capacity;
    for (size_t i = 0; i < storage->class_count; ++i) {
        if (!classes[i].slots.base) continue;
        size_t start = (size_t)(classes[i].slots.base - stack->mapping.base);
        if (start < stack->high) stack->high = start;
    }
}

static void vector_discard_empty_classes(VectorStorage *storage) {
    GrowthRegionPool *classes = (GrowthRegionPool *)storage->region_classes.base;
    for (size_t i = 0; i < storage->class_count; ++i)
        if (!classes[i].slots.used) growth_region_pool_close(&classes[i]);
    vector_refresh_front_boundary(storage);
}

static Source vector_region_slice(VectorStorage *storage, GrowthRegionPool *classes, size_t stride) {
    GrowthStack *stack = &storage->stack;
    Source *arena = &stack->mapping;
    GrowthSpan *high = stack->fronts[GROWTH_HIGH];
    /* A live descending front may still use the gap below its original edge. */
    size_t floor = high ? high->saved_cursor : stack->low;
    // Region strides are aligned, so their high boundary must be aligned too.
    size_t upper = arena->capacity - arena->capacity % _Alignof(max_align_t);
    while (upper >= floor && upper - floor >= stride) {
        /* Search gaps from the high end without shifting occupied classes. */
        size_t lower = floor, preceding = floor;
        for (size_t i = 0; i < storage->class_count; ++i) {
            Source *slots = &classes[i].slots;
            if (!slots->base) continue;
            size_t start = (size_t)(slots->base - arena->base);
            size_t end = start + slots->capacity;
            if (end <= upper && end > lower) {
                lower = end;
                preceding = start;
            }
        }
        size_t count = (upper - lower) / stride;
        if (count > storage->slots) count = storage->slots;
        if (count) {
            size_t capacity = count * stride;
            return (Source){.base = arena->base + upper - capacity, .capacity = capacity,
                            .stride = stride, .stack = 1, .pool = 1};
        }
        upper = preceding;
    }
    return (Source){0};
}

static GrowthRegionPool *vector_region_class(VectorStorage *storage, size_t region_size) {
    size_t offset;
    size_t stride = growth_region_stride(region_size, &offset);
    if (stride > storage->stack.mapping.capacity) return NULL;
    if (!storage->region_classes.base) {
        if (storage->slots > SIZE_MAX / sizeof(GrowthRegionPool))
            fail("table de régions trop grande");
        storage->region_classes = source_stack(storage->slots * sizeof(GrowthRegionPool));
    }
    GrowthRegionPool *classes = (GrowthRegionPool *)storage->region_classes.base;
    GrowthRegionPool *empty = NULL;
    for (size_t i = 0; i < storage->class_count; ++i) {
        if (classes[i].region_size == region_size) return &classes[i];
        if (!classes[i].slots.used && !empty) empty = &classes[i];
    }
    if (empty) {
        growth_region_pool_close(empty);
    }
    Source slots = vector_region_slice(storage, classes, stride);
    if (!slots.base) {
        vector_discard_empty_classes(storage);
        slots = vector_region_slice(storage, classes, stride);
    }
    if (!slots.base) return NULL;
    if (!empty) {
        if (storage->class_count == storage->slots) return NULL;
        empty = &classes[storage->class_count++];
    }
    *empty = (GrowthRegionPool){slots, region_size, offset};
    return empty;
}

static int vector_reserve_region_unlocked(Cell *reserved, uint64_t limit, size_t element_size,
                                 size_t alignment, size_t shorter_slots, int allow_class_creation) {
    if (!reserved || !limit || limit > SIZE_MAX) return 0;
    VectorStorage *storage = reserved->source->vectors;
    if (!storage) return 0;
    size_t capacity = storage->stack.mapping.capacity ? storage->stack.mapping.capacity : VECTOR_STACK_CAPACITY;
    if (limit >= capacity) return 0;
    if (!storage->region_classes.base) {
        if (!allow_class_creation || storage->slots > SIZE_MAX / sizeof(GrowthRegionPool)) return 0;
        size_t offset;
        if (capacity / growth_region_stride((size_t)limit, &offset) <= shorter_slots) return 0;
        Source mapping = {0}, classes;
        if (!storage->stack.mapping.capacity && source_stack_mapping(capacity, &mapping)) return 0;
        if (source_stack_mapping(storage->slots * sizeof(GrowthRegionPool), &classes)) {
            if (mapping.base) source_close(&mapping);
            return 0;
        }
        if (mapping.base)
            storage->stack = (GrowthStack){.mapping = mapping, .high = capacity};
        storage->region_classes = classes;
    }
    GrowthRegionPool *classes = (GrowthRegionPool *)storage->region_classes.base;
    GrowthRegionPool *pool = NULL;
    if (allow_class_creation) {
        pool = vector_region_class(storage, (size_t)limit);
        vector_refresh_front_boundary(storage);
    } else {
        for (size_t i = 0; i < storage->class_count; ++i)
            if (classes[i].region_size == (size_t)limit && classes[i].slots.live) {
                pool = &classes[i];
                break;
            }
    }
    if (!pool || pool->slots.capacity / pool->slots.stride - pool->slots.live <= shorter_slots) return 0;
    VectorItems *items = vector_items(reserved);
    *items = (VectorItems){.element_size = element_size};
    return growth_region_open(pool, &items->region.region, element_size, alignment)
        ? VECTOR_REGION_RESERVED : VECTOR_STORAGE_UNRESERVED;
}

static int vector_reserve_region(Cell *reserved, uint64_t limit, size_t element_size,
                                 size_t alignment, size_t shorter_slots, int allow_class_creation) {
    growth_storage_lock();
    int result = vector_reserve_region_unlocked(reserved, limit, element_size, alignment,
                                                shorter_slots, allow_class_creation);
    growth_storage_unlock();
    return result;
}

static int vector_reserve_front_unlocked(Cell *reserved, size_t element_size, size_t alignment) {
    if (!reserved || !element_size || !reserved->source->vectors) return VECTOR_STORAGE_UNRESERVED;
    VectorStorage *storage = reserved->source->vectors;
    GrowthStack *stack = &storage->stack;
    if (stack->fronts[GROWTH_LOW] || stack->fronts[GROWTH_HIGH]) return VECTOR_STORAGE_UNRESERVED;
    if (!stack->mapping.capacity) {
        Source mapping;
        if (source_stack_mapping(VECTOR_STACK_CAPACITY, &mapping)) return VECTOR_STORAGE_UNRESERVED;
        *stack = (GrowthStack){.mapping = mapping, .high = mapping.capacity};
    }
    vector_discard_empty_classes(storage);
    if ((stack->high - stack->low) / element_size < 2) return VECTOR_STORAGE_UNRESERVED;
    VectorItems *items = vector_items(reserved);
    *items = (VectorItems){.element_size = element_size};
    if (!growth_open(stack, &items->span.span, GROWTH_HIGH, element_size, alignment))
        return VECTOR_STORAGE_UNRESERVED;
    return VECTOR_FRONT_RESERVED;
}

static int vector_reserve_front(Cell *reserved, size_t element_size, size_t alignment) {
    growth_storage_lock();
    int result = vector_reserve_front_unlocked(reserved, element_size, alignment);
    growth_storage_unlock();
    return result;
}

static int vector_reserve_dedicated_front(Cell *reserved, size_t element_size, size_t alignment) {
    if (!reserved || !element_size || element_size > VECTOR_STACK_CAPACITY)
        return VECTOR_STORAGE_UNRESERVED;
    Source mapping;
    if (source_stack_mapping(VECTOR_STACK_CAPACITY, &mapping)) return VECTOR_STORAGE_UNRESERVED;
    VectorItems *items = vector_items(reserved);
    *items = (VectorItems){.element_size = element_size};
    GrowthStack *stack = &items->span.dedicated;
    *stack = (GrowthStack){.mapping = mapping, .high = mapping.capacity};
    if (!growth_open(stack, &items->span.span, GROWTH_LOW, element_size, alignment)) {
        growth_close(stack);
        return VECTOR_STORAGE_UNRESERVED;
    }
    return VECTOR_DEDICATED_RESERVED;
}

static Cell *vector_construct_reserved(Cell *reserved, int storage_reserved, Source *source, uint64_t region_limit,
                                       size_t element_size, size_t alignment, int forward_only,
                                       int owns_handles, const char *label) {
    if (!source->vectors || region_limit > SIZE_MAX) fail("stockage de Vector incompatible");
    Cell *cell = cell_construct_reserved(reserved, source, 0, label);
    VectorStorage *storage = source->vectors;
    VectorItems *items = vector_items(cell);
    if (storage_reserved == VECTOR_REGION_RESERVED) {
        if (!growth_region_is_live(&items->region.region) ||
                items->region.region.pool->region_size != (size_t)region_limit ||
                items->element_size != element_size)
            fail("région réservée incompatible avec la construction");
        items->owns_handles = owns_handles;
        return cell;
    }
    if (storage_reserved == VECTOR_FRONT_RESERVED || storage_reserved == VECTOR_DEDICATED_RESERVED) {
        int dedicated = storage_reserved == VECTOR_DEDICATED_RESERVED;
        GrowthStack *stack = dedicated ? &items->span.dedicated : &storage->stack;
        GrowthFront front = dedicated ? GROWTH_LOW : GROWTH_HIGH;
        GrowthSpan *span = &items->span.span;
        if (region_limit || (forward_only && !dedicated) || items->element_size != element_size ||
                span->stack != stack || stack->fronts[front] != span)
            fail("front réservé incompatible avec la construction");
        items->owns_handles = owns_handles;
        return cell;
    }
    *items = (VectorItems){.element_size = element_size, .owns_handles = owns_handles};
    const size_t capacity = VECTOR_STACK_CAPACITY;
    growth_storage_lock();
    if (!storage->stack.mapping.capacity) storage->stack = growth_stack(capacity);
    if (region_limit) {
        GrowthRegionPool *regions = vector_region_class(storage, (size_t)region_limit);
        vector_refresh_front_boundary(storage);
        if (!growth_region_place(&items->region, regions, (size_t)region_limit, element_size, alignment))
            fail("impossible de placer la région du Vector");
    } else {
        vector_discard_empty_classes(storage);
        if (forward_only) {
            if (growth_open(&storage->stack, &items->span.span, GROWTH_LOW, element_size, alignment) &&
                    element_size > storage->stack.high - storage->stack.low)
                growth_release(&items->span.span);
            if (!items->span.span.stack &&
                    !growth_place(&items->span, NULL, capacity, element_size, alignment))
                fail("impossible de placer le stockage contigu du Vector");
        } else if (!growth_place(&items->span, &storage->stack, capacity, element_size, alignment)) {
            fail("impossible de placer le stockage du Vector");
        }
    }
    growth_storage_unlock();
    return cell;
}

static Cell *vector_new(Source *source, uint64_t region_limit, size_t element_size,
                        size_t alignment, int forward_only, const char *label) {
    return vector_construct_reserved(NULL, 0, source, region_limit, element_size, alignment, forward_only, 0, label);
}

static Cell *vector_new_handles(Source *source, uint64_t region_limit, const char *label) {
    return vector_construct_reserved(NULL, 0, source, region_limit, sizeof(Cell *), _Alignof(Cell *), 0, 1, label);
}

static unsigned char *vector_base(VectorItems *items) {
    GrowthRegion *region = &items->region.region;
    if (region->slot)
        return (unsigned char *)region->slot + region->pool->payload_offset;
    GrowthSpan *span = &items->span.span;
    return span->stack->mapping.base + (span->front == GROWTH_LOW
        ? span->stack->low - items->length * items->element_size : span->stack->high);
}

static int vector_descends(const VectorItems *items) {
    return items->span.span.stack && items->span.span.front == GROWTH_HIGH;
}

static unsigned char *vector_item_at(VectorItems *items, size_t index) {
    if (index >= items->length) return NULL;
    if (vector_descends(items))
        index = items->length - index - 1;
    return vector_base(items) + index * items->element_size;
}

static int vector_values_equal(Cell *left, Cell *right) {
    VectorItems *a = vector_items(left), *b = vector_items(right);
    if (a->length != b->length || a->element_size != b->element_size) return 0;
    for (size_t i = 0; i < a->length; ++i) {
        const unsigned char *x = vector_item_at(a, i), *y = vector_item_at(b, i);
        if (a->element_size == sizeof(int)) {
            int first, second;
            memcpy(&first, x, sizeof first);
            memcpy(&second, y, sizeof second);
            if (first != second) return 0;
        } else if (memcmp(x, y, a->element_size) != 0) {
            return 0;
        }
    }
    return 1;
}

static int vector_try_append(VectorItems *items, const void *source, size_t count, int source_descends) {
    if (count == 0) return 1;
    unsigned char *added;
    if (items->region.region.slot) {
        added = growth_region_extend(&items->region.region, count);
    } else {
        growth_storage_lock();
        added = growth_extend(&items->span.span, count);
        growth_storage_unlock();
    }
    if (!added) return 0;
    size_t size = items->element_size;
    if (vector_descends(items) != source_descends) {
        const unsigned char *element = source;
        for (size_t i = 0; i < count; ++i)
            memcpy(added + (count - i - 1) * size, element + i * size, size);
    } else {
        memmove(added, source, count * size);
    }
    items->length += count;
    return 1;
}

static int vector_try_extend(VectorItems *items, const void *source, size_t count) {
    return vector_try_append(items, source, count, 0);
}

/* Callers validate logical bounds before constructing a view. */
static VectorSlice vector_slice_range(VectorItems *items, size_t first, size_t last) {
    if (first == last) return (VectorSlice){0};
    int descends = vector_descends(items);
    return (VectorSlice){vector_item_at(items, descends ? last - 1 : first),
                         last - first, descends};
}

static VectorSlice vector_slice(Cell *cell, int start, int end, int has_end) {
    VectorItems *items = vector_items(cell);
    if (start < 0 || (has_end && end < start)) fail("bornes de tranche de Vector invalides");
    size_t first = (size_t)start;
    size_t last = has_end ? (size_t)end : items->length;
    if (last > items->length || first > last) fail("bornes de tranche de Vector invalides");
    return vector_slice_range(items, first, last);
}

static VectorSlice vector_subslice(VectorSlice slice, int start, int end, int has_end, size_t element_size) {
    if (start < 0 || (has_end && end < start)) fail("bornes de tranche de Vector invalides");
    size_t first = (size_t)start;
    size_t last = has_end ? (size_t)end : slice.length;
    if (last > slice.length || first > last) fail("bornes de tranche de Vector invalides");
    if (first == last) return (VectorSlice){0};
    size_t offset = slice.descends ? slice.length - last : first;
    return (VectorSlice){slice.base + offset * element_size, last - first, slice.descends};
}

typedef struct {
    VectorSlice left, right;
} VectorSplit;

/* The verifier must reserve the parent while either view can be used. */
static VectorSplit vector_split_at_mut(Cell *cell, int index) {
    VectorItems *items = vector_items(cell);
    if (index < 0 || (size_t)index > items->length)
        fail("indice de séparation de Vector hors limites");
    size_t middle = (size_t)index;
    return (VectorSplit){vector_slice_range(items, 0, middle),
                         vector_slice_range(items, middle, items->length)};
}

static VectorSplit vector_subsplit(VectorSlice slice, int index, size_t element_size) {
    return (VectorSplit){vector_subslice(slice, 0, index, 1, element_size),
                         vector_subslice(slice, index, 0, 0, element_size)};
}

static const unsigned char *vector_slice_address(VectorSlice slice, int index, size_t element_size) {
    if (index < 0 || (size_t)index >= slice.length) fail("indice de tranche de Vector hors limites");
    size_t offset = (size_t)index;
    if (slice.descends) offset = slice.length - offset - 1;
    return slice.base + offset * element_size;
}

static const unsigned char *vector_slice_byte_address(VectorSlice slice, int index) {
    return vector_slice_address(slice, index, 1);
}

static CrustTextResult text_from_vector_slice(VectorSlice slice) {
    if (!slice.descends) return text_from_utf8(slice.base, slice.length);
    CrustText text = {slice.base, slice.length, 1};
    for (size_t offset = 0; offset < text.length;) {
        CrustChar scalar;
        size_t width = text_decode(text, offset, &scalar);
        if (width == 0) return (CrustTextResult){5, {0}};
        offset += width;
    }
    return (CrustTextResult){0, text};
}

static int vector_len(Cell *cell) {
    size_t length = vector_items(cell)->length;
    if (length > INT_MAX) fail("longueur de Vector hors limites Int32");
    return (int)length;
}

enum { CRUST_VECTOR_OK = 0, CRUST_VECTOR_REJECTED = 5, CRUST_VECTOR_CAPACITY = 9 };

static int vector_try_push(Cell *cell, const void *value) {
    return vector_try_extend(vector_items(cell), value, 1) ? CRUST_VECTOR_OK : CRUST_VECTOR_REJECTED;
}

static CrustStatus vector_try_extend_bytes(Cell *cell, const unsigned char *bytes, size_t count) {
    return (CrustStatus){vector_try_extend(vector_items(cell), bytes, count) ?
                         CRUST_VECTOR_OK : CRUST_VECTOR_CAPACITY};
}

static CrustStatus vector_try_extend_slice(Cell *cell, VectorSlice slice) {
    return (CrustStatus){vector_try_append(vector_items(cell), slice.base, slice.length, slice.descends) ?
                         CRUST_VECTOR_OK : CRUST_VECTOR_CAPACITY};
}

static void vector_push(Cell *cell, const void *value) {
    if (!vector_try_extend(vector_items(cell), value, 1)) fail("capacité de Vector dépassée");
}

static void *vector_push_new(Cell *cell, const void *initial) {
    vector_push(cell, initial);
    VectorItems *items = vector_items(cell);
    return vector_item_at(items, items->length - 1);
}

static unsigned char *vector_checked_item(Cell *cell, int index) {
    unsigned char *item = index < 0 ? NULL : vector_item_at(vector_items(cell), (size_t)index);
    if (!item) fail("indice de Vector hors limites");
    return item;
}

static void vector_read(Cell *cell, int index, void *value) {
    memcpy(value, vector_checked_item(cell, index), vector_items(cell)->element_size);
}

static void vector_truncate(VectorItems *items, size_t length) {
    if (length > items->length) fail("réduction de Vector hors limites");
    size_t removed = (items->length - length) * items->element_size;
    if (items->region.region.slot) {
        items->region.region.used -= removed;
    } else {
        growth_storage_lock();
        if (items->span.span.front == GROWTH_LOW) items->span.span.stack->low -= removed;
        else items->span.span.stack->high += removed;
        growth_storage_unlock();
    }
    items->length = length;
}

static CrustCharStatus vector_pop(Cell *cell, void *value) {
    VectorItems *items = vector_items(cell);
    if (!items->length) return CRUST_CHAR_NONE;
    size_t last = items->length - 1;
    memcpy(value, vector_item_at(items, last), items->element_size);
    vector_truncate(items, last);
    return CRUST_CHAR_OK;
}

typedef struct { int status; Cell *value; } VectorHandleResult;
typedef struct { int status; VectorHandleResult value; } CrustOptionJoinResult;
typedef CrustOptionJoinResult CrustExchangeJoinResult;

static int vector_replace(Cell *cell, int index, void *value) {
    VectorItems *items = vector_items(cell);
    unsigned char *item = index < 0 ? NULL : vector_item_at(items, (size_t)index);
    if (!item) return CRUST_VECTOR_REJECTED;
    for (size_t i = 0; i < items->element_size; ++i) {
        unsigned char incoming = ((unsigned char *)value)[i];
        ((unsigned char *)value)[i] = item[i];
        item[i] = incoming;
    }
    return CRUST_VECTOR_OK;
}

typedef enum {
    VECTOR_READ_DATA, VECTOR_READ_EOF, VECTOR_READ_FULL, VECTOR_READ_ERROR
} VectorReadStatus;

typedef struct {
    VectorReadStatus status;
    size_t count;
    int error;
} VectorReadResult;

static VectorReadResult vector_read_fd(Cell *cell, int fd) {
    VectorItems *items = vector_items(cell);
    if (items->element_size != 1) fail("la lecture externe exige un Vector<u8>");
    GrowthRegion *region = &items->region.region;
    GrowthSpan *span = &items->span.span;
    unsigned char *buffer;
    size_t available;
    if (region->slot) {
        buffer = growth_region_extend(region, 0);
        if (!buffer) fail("région de croissance inactive");
        available = region->pool->region_size - region->used;
    } else {
        GrowthStack *stack = span->stack;
        if (!stack || stack->fronts[span->front] != span) fail("front de croissance inactif");
        available = stack->high - stack->low;
        buffer = stack->mapping.base + stack->low;
    }
    if (!available) return (VectorReadResult){.status = VECTOR_READ_FULL};
    size_t limit = available > INT_MAX ? INT_MAX : available;
    ssize_t count = read(fd, buffer, limit);
    if (count < 0) return (VectorReadResult){.status = VECTOR_READ_ERROR, .error = errno};
    if (!count) return (VectorReadResult){.status = VECTOR_READ_EOF};

    size_t received = (size_t)count;
    if (region->slot) {
        growth_region_extend(region, received);
    } else {
        unsigned char *published = growth_extend(span, received);
        if (span->front == GROWTH_HIGH) {
            memmove(published, buffer, received);
            for (size_t i = 0; i < received / 2; ++i) {
                unsigned char first = published[i];
                published[i] = published[received - i - 1];
                published[received - i - 1] = first;
            }
        }
    }
    items->length += received;
    return (VectorReadResult){.status = VECTOR_READ_DATA, .count = received};
}

static CrustIntPayload vector_read_int(Cell *cell, int fd) {
    VectorReadResult result = vector_read_fd(cell, fd);
    switch (result.status) {
        case VECTOR_READ_DATA: return (CrustIntPayload){0, (int)result.count};
        case VECTOR_READ_EOF: return (CrustIntPayload){10, 0};
        case VECTOR_READ_FULL: return (CrustIntPayload){11, 0};
        case VECTOR_READ_ERROR: return (CrustIntPayload){12, 0};
    }
    fail("état de lecture externe inconnu");
}

static void vector_remove(Cell *cell, int index, void *value) {
    VectorItems *items = vector_items(cell);
    vector_read(cell, index, value);
    for (size_t i = (size_t)index; i + 1 < items->length; ++i)
        memcpy(vector_item_at(items, i), vector_item_at(items, i + 1), items->element_size);
    vector_truncate(items, items->length - 1);
}

static Cell *string_new(Source *source, uint64_t region_limit, const char *label) {
    return vector_new(source, region_limit, 1, 1, 1, label);
}

static CrustText string_view(Cell *cell) {
    VectorItems *items = vector_items(cell);
    return (CrustText){vector_base(items), items->length, vector_descends(items)};
}

static int string_byte_len(Cell *cell) {
    size_t length = vector_items(cell)->length;
    if (length > INT_MAX) fail("longueur de String hors limites Int32");
    return (int)length;
}

static void string_push_str(Cell *cell, CrustText text) {
    if (!vector_try_append(vector_items(cell), text.bytes, text.length, text.descends))
        fail("capacité de String dépassée");
}

static void string_push(Cell *cell, CrustChar value) {
    unsigned char encoded[4];
    int width = char_encode(value, encoded);
    string_push_str(cell, (CrustText){encoded, (size_t)width, 0});
}

static CrustCharResult string_pop(Cell *cell) {
    VectorItems *items = vector_items(cell);
    CrustText text = string_view(cell);
    if (text.length == 0) return (CrustCharResult){CRUST_CHAR_NONE, 0};
    size_t start = text.length - 1;
    while (start > 0 && !text_is_boundary(text, start)) --start;
    CrustChar value;
    size_t width = text_decode(text, start, &value);
    if (width == 0 || width != text.length - start) fail("invariant interne : String UTF-8 invalide");
    vector_truncate(items, start);
    return (CrustCharResult){CRUST_CHAR_OK, value};
}

static uint8_t byte_result_value(CrustByteResult result) {
    if (result.status != 0) fail("résultat UTF-8 sans octet");
    return result.value;
}

/* Validate the prospective bytes through a four-byte window. No write to
 * the live String is needed until the complete replacement is known valid. */
static unsigned char replacement_byte(VectorSlice replacement, size_t index) {
    return replacement.base[replacement.descends ? replacement.length - index - 1 : index];
}

static int text_replacement_valid(CrustText text, size_t start, VectorSlice replacement) {
    for (size_t pos = 0; pos < text.length;) {
        unsigned char window[4];
        size_t size = text.length - pos;
        if (size > sizeof window) size = sizeof window;
        for (size_t i = 0; i < size; ++i) {
            size_t index = pos + i;
            window[i] = index >= start && index - start < replacement.length
                ? replacement_byte(replacement, index - start) : *text_address(text, index);
        }
        CrustChar scalar;
        size_t width = utf8_decode(window, size, &scalar);
        if (!width) return 0;
        pos += width;
    }
    return 1;
}

static CrustByteResult string_replace_slice(Cell *cell, int index, VectorSlice replacement) {
    CrustText text = string_view(cell);
    size_t count = replacement.length;
    if (index < 0 || (size_t)index > text.length || count > text.length - (size_t)index)
        return (CrustByteResult){7, 0};
    if (count == 0) return (CrustByteResult){0, 0};
    if (!text_replacement_valid(text, (size_t)index, replacement))
        return (CrustByteResult){8, 0};
    size_t first = (size_t)index;
    uint8_t previous = *text_address(text, first);
    size_t offset = text.descends ? text.length - first - count : first;
    unsigned char *target = (unsigned char *)text.bytes + offset;
    if (replacement.descends != text.descends) {
        for (size_t i = 0; i < count; ++i)
            target[count - i - 1] = replacement.base[i];
    } else {
        memmove(target, replacement.base, count);
    }
    return (CrustByteResult){0, previous};
}

static CrustByteResult string_replace_bytes(Cell *cell, int index,
                                            const unsigned char *replacement, size_t count) {
    return string_replace_slice(cell, index, (VectorSlice){replacement, count, 0});
}

static CrustByteResult string_replace_byte(Cell *cell, int index, uint8_t replacement) {
    return string_replace_bytes(cell, index, &replacement, 1);
}

static void vector_drop(Cell *cell) {
    VectorItems *items = vector_items(cell);
    if (items->owns_handles) {
        for (size_t i = items->length; i > 0; --i) {
            Cell *element;
            memcpy(&element, vector_item_at(items, i - 1), sizeof element);
            cell_drop(element);
        }
    }
    growth_storage_lock();
    if (items->region.region.slot) growth_region_unplace(&items->region);
    else growth_unplace(&items->span);
    VectorStorage *storage = cell->source->vectors;
    if (storage->stack.fronts[GROWTH_LOW] || storage->stack.fronts[GROWTH_HIGH])
        vector_discard_empty_classes(storage);
    else
        vector_refresh_front_boundary(storage);
    growth_storage_unlock();
}

static void vector_storage_close(VectorStorage *storage) {
    GrowthRegionPool *classes = (GrowthRegionPool *)storage->region_classes.base;
    for (size_t i = 0; i < storage->class_count; ++i) growth_region_pool_close(&classes[i]);
    if (classes) source_close(&storage->region_classes);
    storage->region_classes = (Source){0};
    storage->class_count = 0;
    if (storage->stack.mapping.capacity) growth_close(&storage->stack);
}

/* A view carries its root and offset by value. It never points at another
   view descriptor, so returning it cannot retain a callee's stack variable. */
static CrustStructureView structure_view(Cell *root, size_t offset, size_t size,
                                         const Source *layout) {
    if (!root || !root->alive || !layout || root->storage_size < sizeof(Cell))
        fail("invalid structure view root");
    size_t available = root->storage_size - sizeof(Cell);
    if (offset > available || size > available - offset)
        fail("structure view outside allocation");
    return (CrustStructureView){root, offset, size, layout};
}

static CrustStructureView structure_subview(CrustStructureView parent, size_t offset,
                                            size_t size, const Source *layout) {
    if (offset > parent.size || size > parent.size - offset || offset > SIZE_MAX - parent.offset)
        fail("structure subview outside parent");
    return structure_view(parent.root, parent.offset + offset, size, layout);
}

static CrustStructureView structure_whole_view(Cell *cell) {
    return structure_view(cell, 0, cell->storage_size - sizeof(Cell), cell->layout);
}
static CrustStructureView structure_reference_identity(CrustStructureView view) { return view; }
static Cell *cell_reference_identity(Cell *cell) { return cell; }

/* The destination's type is fixed after all branches have been checked.
   Convert only the representation, without allocating or moving the target. */
#define structure_reference_for(destination,value) _Generic((destination), \
    CrustStructureView: _Generic((value), CrustStructureView: structure_reference_identity, default: structure_whole_view), \
    default: cell_reference_identity)(value)

static unsigned char *structure_view_address(CrustStructureView view, size_t offset,
                                             size_t width) {
    if (!view.root || !view.root->alive)
        fail("inactive structure view root");
    if (offset > view.size || width > view.size - offset)
        fail("structure field outside view");
    return (unsigned char *)view.root->fields + view.offset + offset;
}

static void *structure_reference_address(CrustStructureView view) {
    unsigned char *payload = structure_view_address(view, 0, 0);
    return view.offset == 0 && view.layout == view.root->layout ? (void *)view.root : (void *)payload;
}

static int structure_view_load_int(CrustStructureView view, size_t offset) {
    int value;
    memcpy(&value, structure_view_address(view, offset, sizeof value), sizeof value);
    return value;
}

static void structure_view_store_int(CrustStructureView view, size_t offset, int value) {
    memcpy(structure_view_address(view, offset, sizeof value), &value, sizeof value);
}

static Cell *structure_view_load_ref(CrustStructureView view, size_t offset) {
    Cell *value;
    memcpy(&value, structure_view_address(view, offset, sizeof value), sizeof value);
    return value;
}

static void structure_view_store_ref(CrustStructureView view, size_t offset, Cell *value) {
    (void)structure_view_address(view, offset, sizeof value);
    cell_store_ref(view.root, view.offset + offset, value);
}

static CrustStructureView cell_load_view(Cell *cell, size_t offset) {
    CrustStructureView value;
    memcpy(&value, (unsigned char *)cell->fields + offset, sizeof value);
    return structure_view(value.root, value.offset, value.size, value.layout);
}

static void cell_store_view(Cell *cell, size_t offset, CrustStructureView value) {
    memcpy((unsigned char *)cell->fields + offset, &value, sizeof value);
}

static CrustStructureView structure_view_load_view(CrustStructureView view, size_t offset) {
    (void)structure_view_address(view, offset, sizeof(CrustStructureView));
    return cell_load_view(view.root, view.offset + offset);
}

static void structure_view_store_view(CrustStructureView view, size_t offset, CrustStructureView value) {
    (void)structure_view_address(view, offset, sizeof value);
    cell_store_view(view.root, view.offset + offset, value);
}

static void structure_view_print(CrustStructureView view) {
    printf("%s(", view.layout->enum_name);
    for (size_t i=0;i<view.layout->field_count;++i) {
        size_t offset=view.layout->field_offsets[i];
        int value=view.layout->field_kinds[i]
            ? structure_view_load_ref(view,offset)->value : structure_view_load_int(view,offset);
        printf(i ? ", %d" : "%d",value);
    }
    puts(")");
}

/* Bodies are specialized for the concrete reference representation. */
#define cell_load_int(cell,offset) _Generic((cell), CrustStructureView: structure_view_load_int, default: cell_load_int)(cell,offset)
#define cell_store_int(cell,offset,value) _Generic((cell), CrustStructureView: structure_view_store_int, default: cell_store_int)(cell,offset,value)
#define cell_load_ref(cell,offset) _Generic((cell), CrustStructureView: structure_view_load_ref, default: cell_load_ref)(cell,offset)
#define cell_store_ref(cell,offset,value) _Generic((cell), CrustStructureView: structure_view_store_ref, default: cell_store_ref)(cell,offset,value)
#define cell_print(cell) _Generic((cell), CrustStructureView: structure_view_print, default: cell_print)(cell)
#define cell_load_view(cell,offset) _Generic((cell), CrustStructureView: structure_view_load_view, default: cell_load_view)(cell,offset)
#define cell_store_view(cell,offset,value) _Generic((cell), CrustStructureView: structure_view_store_view, default: cell_store_view)(cell,offset,value)



typedef struct { int status; CrustOptionJoinResult value; } CrustOptionJoinResult2;
typedef struct { int status; CrustOptionJoinResult2 value; } CrustOptionJoinResult3;

#include <stdatomic.h>
#include <stdint.h>

typedef struct {
    int status;
    CrustJoinResult value;
} CrustNestedJoinResult;

typedef struct CrustTask CrustTask;
typedef struct CrustQueueEntry CrustQueueEntry;
typedef struct { CrustQueueEntry *entry; uint64_t generation; } CrustWakeTicket;

typedef enum {
    TASK_INACTIVE, TASK_QUEUED, TASK_RUNNING, TASK_SUSPENDED, TASK_COMPLETE, TASK_CONSUMED
} CrustTaskState;

typedef enum {
    TASK_STEP_YIELD, TASK_STEP_RETURN, TASK_STEP_PENDING
} CrustTaskStep;

typedef struct {
    CrustTaskStep (*resume)(CrustTask *);
    void (*take_result)(CrustTask *, void *);
    void (*release)(CrustTask *);
} CrustTaskOps;

struct CrustTask {
    _Atomic CrustTaskState state;
    _Atomic int worker_done;
    _Atomic int scheduling_lock;
    int ready; /* Protected by scheduling_lock, including during a poll. */
    CrustQueueEntry *queue_entry; /* Stable scheduler storage, when generated. */
    CrustWakeTicket wake_target; /* Root poll owning a chain of direct awaits. */
    const CrustTaskOps *ops;
    int (*can_discard_suspended)(CrustTask *);
    void (*discard_suspended)(CrustTask *);
};

static void task_init(CrustTask *task, const CrustTaskOps *ops) {
    task->ops = ops;
    atomic_init(&task->state, TASK_INACTIVE);
    atomic_init(&task->worker_done, 0);
    atomic_init(&task->scheduling_lock, 0);
    task->ready = 1;
    task->queue_entry = NULL;
    task->wake_target = (CrustWakeTicket){0};
    task->can_discard_suspended = NULL;
    task->discard_suspended = NULL;
}

/* Only short bookkeeping sections hold this gate, never user code. Callers
   must keep the task alive until their poll/wake calls have returned. */
static void task_scheduling_lock(CrustTask *task) {
    int expected = 0;
    while (!atomic_compare_exchange_weak_explicit(&task->scheduling_lock,
            &expected, 1, memory_order_acquire, memory_order_relaxed)) expected = 0;
}

static void task_scheduling_unlock(CrustTask *task) {
    atomic_store_explicit(&task->scheduling_lock, 0, memory_order_release);
}

static int task_wake(CrustTask *task) {
    /* Primitive readiness update. External producers for a queued task use
       task_queue_wake so that a waiting task is also placed on its queue. */
    task_scheduling_lock(task);
    CrustTaskState state = atomic_load(&task->state);
    int live = state != TASK_COMPLETE && state != TASK_CONSUMED;
    if (live) task->ready = 1;
    task_scheduling_unlock(task);
    return live;
}

static CrustTaskState task_resume_claimed(CrustTask *task) {
    CrustTaskStep step = task->ops->resume(task);
    CrustTaskState next = step == TASK_STEP_RETURN ? TASK_COMPLETE : TASK_SUSPENDED;
    task_scheduling_lock(task);
    /* Pending keeps a wake received during resume. Yield makes itself ready. */
    if (step == TASK_STEP_YIELD) task->ready = 1;
    atomic_store(&task->state, next);
    task_scheduling_unlock(task);
    return next;
}

static CrustTaskState task_poll(CrustTask *task) {
    task_scheduling_lock(task);
    CrustTaskState state = atomic_load(&task->state);
    if ((state == TASK_INACTIVE || state == TASK_SUSPENDED) && task->ready) {
        if (atomic_compare_exchange_strong(&task->state, &state, TASK_RUNNING)) {
            task->ready = 0;
            task_scheduling_unlock(task);
            return task_resume_claimed(task);
        }
    }
    task_scheduling_unlock(task);
    return state;
}

static int task_consume(CrustTask *task, CrustTaskState expected) {
    task_scheduling_lock(task);
    int consumed = atomic_compare_exchange_strong(&task->state, &expected, TASK_CONSUMED);
    task_scheduling_unlock(task);
    return consumed;
}

static CrustTaskState task_poll_child(CrustTask *parent, CrustTask *child) {
    child->wake_target = parent->wake_target;
    /* A resumed parent rechecks its awaited chain. No child is polled in
       parallel: direct await owns it and executes it on the parent's thread. */
    task_wake(child);
    return task_poll(child);
}
static CrustTaskStep task_child_suspension(CrustTask *child) {
    task_scheduling_lock(child);
    int ready = child->ready;
    task_scheduling_unlock(child);
    return ready ? TASK_STEP_YIELD : TASK_STEP_PENDING;
}

static int task_take(CrustTask *task, void *result) {
    if (!task_consume(task, TASK_COMPLETE)) return 0;
    task->ops->take_result(task, result);
    task->ops->release(task);
    return 1;
}

static int task_drop_inactive(CrustTask *task) {
    if (!task_consume(task, TASK_INACTIVE)) return 0;
    task->ops->release(task);
    return 1;
}

static int task_drop_complete(CrustTask *task) {
    if (!task_consume(task, TASK_COMPLETE)) return 0;
    task->ops->release(task);
    return 1;
}

/* Private owned-state destruction used by Select cleanup. The caller has
   exclusive ownership of the whole direct-await tree, has revoked external
   wake routes, and never uses this on a scheduled execution handle. Preflight
   the tree before consuming anything, including captures of inactive children. */
static int task_owned_discardable(CrustTask *task) {
    CrustTaskState state = atomic_load(&task->state);
    if (state == TASK_INACTIVE || state == TASK_COMPLETE) return 1;
    return state == TASK_SUSPENDED && task->can_discard_suspended &&
        task->discard_suspended && task->can_discard_suspended(task);
}

static int task_drop_owned(CrustTask *task) {
    if (!task_owned_discardable(task)) return 0;
    CrustTaskState state = atomic_load(&task->state);
    if (!task_consume(task, state)) return 0;
    if (state == TASK_SUSPENDED) task->discard_suspended(task);
    else task->ops->release(task);
    return 1;
}

#include <stddef.h>
#include <stdint.h>
#include <stdint.h>
#include <stdatomic.h>

typedef struct {
    unsigned char *storage;
    size_t stride;
    size_t count;
    _Atomic size_t *generations;
} CrustTaskPool;

typedef struct {
    CrustTaskPool *pool;
    size_t index;
    size_t generation;
} CrustTaskSlot;

static void task_pool_init(CrustTaskPool *pool, void *storage, size_t stride,
                           size_t count, _Atomic size_t *generations) {
    *pool = (CrustTaskPool){storage, stride, count, generations};
    for (size_t i = 0; i < count; ++i) atomic_init(&generations[i], 0);
}

static CrustTaskSlot task_pool_acquire(CrustTaskPool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        size_t generation = atomic_load(&pool->generations[i]);
        /* Even generations are free. Retire the final even generation
           rather than letting an obsolete ticket become valid again. */
        if (generation % 2 || generation == SIZE_MAX - 1) continue;
        if (atomic_compare_exchange_strong(&pool->generations[i], &generation, generation + 1))
            return (CrustTaskSlot){pool, i, generation + 1};
    }
    return (CrustTaskSlot){0};
}

static void *task_slot_address(CrustTaskSlot slot) {
    if (!slot.pool || slot.index >= slot.pool->count || slot.generation % 2 == 0 ||
            atomic_load(&slot.pool->generations[slot.index]) != slot.generation) return NULL;
    return slot.pool->storage + slot.index * slot.pool->stride;
}

static int task_pool_release(CrustTaskSlot slot) {
    if (!slot.pool || slot.index >= slot.pool->count ||
            slot.generation % 2 == 0 || slot.generation == SIZE_MAX) return 0;
    return atomic_compare_exchange_strong(&slot.pool->generations[slot.index],
                                          &slot.generation, slot.generation + 1);
}

/* The owner calls this after synchronizing with any threads using the pool. */
static int task_pool_is_empty(const CrustTaskPool *pool) {
    for (size_t i = 0; i < pool->count; ++i)
        if (atomic_load(&pool->generations[i]) % 2) return 0;
    return 1;
}

static void task_discard(CrustTask *);

#include <errno.h>
#include <pthread.h>
#include <sched.h>
#include <stdlib.h>

/* Internal boundary. Success transfers one run invocation to a new thread.
   Failure leaves data untouched. wait synchronizes with a joinable launch.
   detach is optional and releases the native handle without waiting or
   reentering the abandoned-task registry. */
typedef struct {
    int (*launch)(pthread_t *, int detached, void *(*run)(void *), void *);
    int (*wait)(pthread_t);
    int (*detach)(pthread_t);
    int (*launch_blocking)(pthread_t *, int detached, void *(*run)(void *), void *);
} CrustThreadScheduler;

static int task_pthread_launch(pthread_t *thread, int detached, void *(*run)(void *), void *data) {
    (void)thread;
    (void)run;
    (void)data;
    if (!detached) return pthread_create(thread, NULL, run, data);
    pthread_attr_t attr;
    int error = pthread_attr_init(&attr);
    if (error) return error;
    error = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    if (!error) error = pthread_create(thread, &attr, run, data);
    pthread_attr_destroy(&attr);
    return error;
}

static int task_pthread_wait(pthread_t thread) {
    return pthread_join(thread, NULL);
}

static const CrustThreadScheduler task_default_scheduler = {
    .launch = task_pthread_launch, .wait = task_pthread_wait, .detach = pthread_detach,
    .launch_blocking = task_pthread_launch
};

static int task_default_submit(CrustTask *task);
static void task_default_wait(CrustTask *task);
static void task_default_close(void);
static int task_external_register(CrustTask *task);
static void task_external_forget(CrustTask *task);
static void task_external_complete(CrustTask *task);

typedef struct {
    pthread_t thread;
    int (*wait)(pthread_t);
    int (*detach)(pthread_t);
    CrustTask *task;
    _Atomic int joined;
    int error;
    int pooled;
} CrustExecution;


typedef struct {
    pthread_t thread;
    int (*wait)(pthread_t);
    int (*detach)(pthread_t);
    CrustTask *task;
    int detached;
    int pooled;
} CrustAbandonedExecution;

typedef struct {
    CrustAbandonedExecution *entries;
    size_t count, capacity;
} CrustAbandonedTasks;

static void task_claim_queued(CrustTask *task) {
    task_scheduling_lock(task);
    CrustTaskState queued = TASK_QUEUED;
    if (!atomic_compare_exchange_strong(&task->state, &queued, TASK_RUNNING)) abort();
    task->ready = 0;
    task_scheduling_unlock(task);
}

static void *task_thread_run(void *pointer) {
    CrustTask *task = pointer;
    task_claim_queued(task);
    CrustTaskState state = task_resume_claimed(task);
    while (state == TASK_SUSPENDED) {
        sched_yield();
        state = task_poll(task);
    }
    if (state != TASK_COMPLETE) abort();
    /* Last access to the task slot, for both kinds of launch. */
    task_external_complete(task);
    return NULL;
}

/* A native block is synchronous: invoke it exactly once. A yielded step here
   is a compiler/runtime contract violation, not a request to schedule it. */
static void *task_native_run(void *pointer) {
    CrustTask *task = pointer;
    task_claim_queued(task);
    if (task_resume_claimed(task) != TASK_COMPLETE) abort();
    /* No access to the task slot is allowed after this publication. */
    task_external_complete(task);
    return NULL;
}

static int task_start_joinable(CrustExecution *execution, CrustTask *task,
        int (*launch)(pthread_t *, int, void *(*)(void *), void *),
        int (*wait)(pthread_t), int (*detach)(pthread_t), void *(*run)(void *)) {
    CrustTaskState inactive = TASK_INACTIVE;
    if (!atomic_compare_exchange_strong(&task->state, &inactive, TASK_QUEUED)) return EINVAL;
    execution->task = task;
    execution->pooled = 0;
    atomic_init(&execution->joined, 0);
    execution->wait = wait;
    execution->detach = detach;
    int error = task_external_register(task);
    if (!error) error = launch ? launch(&execution->thread, 0, run, task) : ENOTSUP;
    execution->error = error;
    if (error) {
        task_external_forget(task);
        atomic_store(&task->state, TASK_INACTIVE);
        if (!task_drop_inactive(task)) abort();
        execution->task = NULL;
    }
    return error;
}

static int task_thread_start_mode(CrustExecution *execution, CrustTask *task,
                                  const CrustThreadScheduler *scheduler, int blocking) {
    if (scheduler == &task_default_scheduler && !blocking && task->queue_entry) {
        if (atomic_load(&task->state) != TASK_INACTIVE) return EINVAL;
        execution->task = task;
        execution->pooled = 1;
        execution->thread = (pthread_t){0};
        execution->wait = NULL;
        execution->detach = NULL;
        atomic_init(&execution->joined, 0);
        int error = task_default_submit(task);
        execution->error = error;
        if (error) {
            if (error == EINVAL) return error;
            if (!task_drop_inactive(task)) abort();
            execution->task = NULL;
        }
        return error;
    }
    return task_start_joinable(execution, task,
        blocking ? scheduler->launch_blocking : scheduler->launch,
        scheduler->wait, scheduler->detach, task_thread_run);
}

static int task_native_start(CrustExecution *execution, CrustTask *task) {
    return task_start_joinable(execution, task, task_pthread_launch,
                              task_pthread_wait, pthread_detach, task_native_run);
}

static int task_thread_start_with(CrustExecution *execution, CrustTask *task,
                                  const CrustThreadScheduler *scheduler) {
    return task_thread_start_mode(execution, task, scheduler, 0);
}

static int task_thread_start_blocking_with(CrustExecution *execution, CrustTask *task,
                                          const CrustThreadScheduler *scheduler) {
    return task_thread_start_mode(execution, task, scheduler, 1);
}

static int task_thread_start_blocking(CrustExecution *execution, CrustTask *task) {
    return task_thread_start_blocking_with(execution, task, &task_default_scheduler);
}

static int task_thread_start(CrustExecution *execution, CrustTask *task) {
    return task_thread_start_with(execution, task, &task_default_scheduler);
}

static int task_thread_join(CrustExecution *execution, void *result) {
    if (!execution->task || atomic_exchange(&execution->joined, 1)) return 0;
    /* A system join failure cannot establish that the task has terminated. */
    if (execution->pooled) task_default_wait(execution->task);
    else if (execution->wait(execution->thread) != 0) abort();
    if (!task_take(execution->task, result)) abort();
    return 1;
}

static CrustJoinResult task_join_into(CrustExecution *execution, void *out) {
    CrustJoinResult result = {0};
    if (execution->error) result.status = CRUST_RUNTIME_LAUNCH_FAILED;
    else if (!task_thread_join(execution, out)) abort();
    return result;
}

static CrustJoinResult task_join_result(CrustExecution *execution) {
    int value = 0;
    CrustJoinResult result = task_join_into(execution, &value);
    result.value = value;
    return result;
}

static CrustJoinResult task_join_allocation(CrustExecution *execution) {
    CrustJoinResult result = {0};
    if (execution->error) result.status = CRUST_RUNTIME_LAUNCH_FAILED;
    else if (!task_thread_join(execution, &result.allocation)) abort();
    return result;
}

static CrustNestedJoinResult task_join_nested(CrustExecution *execution) {
    CrustNestedJoinResult result = {0};
    if (execution->error) result.status = CRUST_RUNTIME_LAUNCH_FAILED;
    else if (!task_thread_join(execution, &result.value)) abort();
    return result;
}

static CrustJoinResult task_join_reference(CrustExecution *execution, int mutable) {
    CrustJoinResult result = {0};
    if (execution->error) result.status = CRUST_RUNTIME_LAUNCH_FAILED;
    else {
        void *out = mutable ? (void *)&result.mutable_reference : (void *)&result.reference;
        if (!task_thread_join(execution, out)) abort();
    }
    return result;
}

/* Registration may race with draining a parent that is still running.
   Release the lock before waiting, so that parent can register children. */
static pthread_mutex_t abandoned_mutex = PTHREAD_MUTEX_INITIALIZER;

static void task_register_abandoned(CrustAbandonedTasks *tasks, CrustAbandonedExecution execution) {
    if (pthread_mutex_lock(&abandoned_mutex) != 0) abort();
    if (tasks->count == tasks->capacity) abort();
    tasks->entries[tasks->count++] = execution;
    if (pthread_mutex_unlock(&abandoned_mutex) != 0) abort();
}

static void task_thread_abandon(CrustAbandonedTasks *tasks, CrustExecution *execution) {
    if (atomic_exchange(&execution->joined, 1)) abort();
    if (!execution->task) return;
    task_register_abandoned(tasks, (CrustAbandonedExecution){
        .thread = execution->thread, .wait = execution->wait, .detach = execution->detach,
        .task = execution->task, .pooled = execution->pooled
    });
}

static void task_thread_reap(CrustAbandonedTasks *tasks) {
    for (;;) {
        CrustTask *completed = NULL;
        if (pthread_mutex_lock(&abandoned_mutex) != 0) abort();
        for (size_t i = 0; i < tasks->count; ++i) {
            CrustAbandonedExecution *execution = &tasks->entries[i];
            if (!atomic_load_explicit(&execution->task->worker_done, memory_order_acquire)) continue;
            if (!execution->pooled && !execution->detached && (!execution->detach || execution->detach(execution->thread))) continue;
            completed = execution->task;
            *execution = tasks->entries[--tasks->count];
            break;
        }
        if (pthread_mutex_unlock(&abandoned_mutex) != 0) abort();
        if (!completed) return;
        if (!task_drop_complete(completed)) abort();
    }
}

static void task_thread_drain(CrustAbandonedTasks *tasks) {
    for (;;) {
        if (pthread_mutex_lock(&abandoned_mutex) != 0) abort();
        if (!tasks->count) {
            if (pthread_mutex_unlock(&abandoned_mutex) != 0) abort();
            return;
        }
        CrustAbandonedExecution execution = tasks->entries[--tasks->count];
        if (pthread_mutex_unlock(&abandoned_mutex) != 0) abort();
        if (execution.pooled) task_default_wait(execution.task);
        else if (execution.detached) {
            while (!atomic_load_explicit(&execution.task->worker_done, memory_order_acquire))
                sched_yield();
        } else if (execution.wait(execution.thread) != 0) abort();
        if (!task_drop_complete(execution.task)) abort();
    }
}


/* Entries live in scheduler storage, independently of task frames. A ticket
   may outlive a frame, but never its entry. Entry storage is retired only after
   all workers and event producers using it have stopped. No heap allocation. */
typedef struct CrustReadyQueue CrustReadyQueue;
struct CrustQueueEntry {
    pthread_mutex_t mutex;
    CrustReadyQueue *queue;
    CrustTask *task;
    uint64_t generation;
    CrustWakeTicket waiter;
    CrustWakeTicket forward; /* Select branch -> enclosing poll, never a frame pointer. */
    int scheduled; /* Queued, claimed by a worker, or currently being polled. */
    CrustQueueEntry *next; /* Queue mutex, not entry mutex. */
};
struct CrustReadyQueue {
    pthread_mutex_t mutex;
    pthread_cond_t changed;
    CrustQueueEntry *head, *tail;
    size_t outstanding;
    int closed;
};

static void task_queue_lock(pthread_mutex_t *mutex) {
    if (pthread_mutex_lock(mutex)) abort();
}
static void task_queue_unlock(pthread_mutex_t *mutex) {
    if (pthread_mutex_unlock(mutex)) abort();
}
static int task_queue_init(CrustReadyQueue *queue) {
    int error = pthread_mutex_init(&queue->mutex, NULL);
    if (error) return error;
    error = pthread_cond_init(&queue->changed, NULL);
    if (error) {
        if (pthread_mutex_destroy(&queue->mutex)) abort();
        return error;
    }
    queue->head = queue->tail = NULL;
    queue->outstanding = 0;
    queue->closed = 0;
    return 0;
}
static void task_queue_entry_init(CrustQueueEntry *entry) {
    if (pthread_mutex_init(&entry->mutex, NULL)) abort();
    entry->queue = NULL;
    entry->task = NULL;
    entry->generation = 0;
    entry->waiter = (CrustWakeTicket){0};
    entry->forward = (CrustWakeTicket){0};
    entry->scheduled = 0;
    entry->next = NULL;
}
/* Caller holds both entry and queue mutexes. No consumer holds the queue
   mutex while acquiring an entry mutex: the lock order cannot be reversed. */
static void task_queue_push_locked(CrustReadyQueue *queue, CrustQueueEntry *entry) {
    entry->next = NULL;
    if (queue->tail) queue->tail->next = entry;
    else queue->head = entry;
    queue->tail = entry;
    entry->scheduled = 1;
    if (pthread_cond_broadcast(&queue->changed)) abort();
}
static void task_queue_push(CrustReadyQueue *queue, CrustQueueEntry *entry) {
    task_queue_lock(&queue->mutex);
    if (queue->closed) abort();
    task_queue_push_locked(queue, entry);
    task_queue_unlock(&queue->mutex);
}
static int task_queue_submit(CrustReadyQueue *queue, CrustQueueEntry *entry,
                             CrustTask *task, CrustWakeTicket *ticket) {
    int error = 0;
    task_queue_lock(&entry->mutex);
    task_queue_lock(&queue->mutex);
    if (entry->task || entry->scheduled) error = EBUSY;
    else if (queue->closed) error = EPIPE;
    else if (entry->generation == UINT64_MAX) error = EOVERFLOW;
    else {
        CrustTaskState inactive = TASK_INACTIVE;
        if (!atomic_compare_exchange_strong(&task->state, &inactive, TASK_QUEUED)) error = EINVAL;
        else {
            ++entry->generation;
            entry->queue = queue;
            entry->task = task;
            task->queue_entry = entry;
            ++queue->outstanding;
            *ticket = (CrustWakeTicket){entry, entry->generation};
            task->wake_target = *ticket;
            entry->waiter = (CrustWakeTicket){0};
            entry->forward = (CrustWakeTicket){0};
            task_queue_push_locked(queue, entry);
        }
    }
    task_queue_unlock(&queue->mutex);
    task_queue_unlock(&entry->mutex);
    return error;
}
static int task_queue_wake(CrustWakeTicket ticket) {
    CrustQueueEntry *entry = ticket.entry;
    if (!entry) return 0;
    task_queue_lock(&entry->mutex);
    int valid = entry->generation == ticket.generation && entry->task;
    CrustWakeTicket forward = {0};
    if (valid) {
        valid = task_wake(entry->task);
        if (valid && !entry->scheduled) task_queue_push(entry->queue, entry);
        if (valid) forward = entry->forward;
    }
    task_queue_unlock(&entry->mutex);
    /* Never nest entry locks. A detached/reused enclosing entry rejects the
       saved generation; no task frame is retained across this notification. */
    if (forward.entry) task_queue_wake(forward);
    return valid;
}

static int task_external_register(CrustTask *task) {
    CrustQueueEntry *entry = task->queue_entry;
    if (!entry) return 0;
    task_queue_lock(&entry->mutex);
    int error = entry->task || entry->scheduled ? EBUSY :
                entry->generation == UINT64_MAX ? EOVERFLOW : 0;
    if (!error) {
        ++entry->generation;
        entry->queue = NULL;
        entry->task = task;
        entry->scheduled = 1; /* Dedicated worker or owned Select branch; never enqueued. */
        entry->waiter = (CrustWakeTicket){0};
        entry->forward = (CrustWakeTicket){0};
        task->wake_target = (CrustWakeTicket){entry, entry->generation};
    }
    task_queue_unlock(&entry->mutex);
    return error;
}
static void task_external_forget(CrustTask *task) {
    CrustQueueEntry *entry = task->queue_entry;
    if (!entry) return;
    task_queue_lock(&entry->mutex);
    if (entry->task == task) {
        entry->task = NULL;
        entry->scheduled = 0;
        entry->waiter = (CrustWakeTicket){0};
        entry->forward = (CrustWakeTicket){0};
    }
    task_queue_unlock(&entry->mutex);
}
static void task_external_complete(CrustTask *task) {
    CrustQueueEntry *entry = task->queue_entry;
    CrustWakeTicket waiter = {0};
    if (entry) {
        task_queue_lock(&entry->mutex);
        if (entry->task != task || entry->queue) abort();
        waiter = entry->waiter;
        entry->waiter = (CrustWakeTicket){0};
        entry->task = NULL;
        entry->scheduled = 0;
        task_queue_unlock(&entry->mutex);
    }
    /* Notify before the final frame access: a detached thread must not retain
       a ticket into the context after its completion becomes observable. */
    task_queue_wake(waiter);
    /* Completion notification finished. */
    atomic_store_explicit(&task->worker_done, 1, memory_order_release);
}

static CrustTaskStep task_subscribe(CrustTask *child, CrustTask *parent) {
    CrustQueueEntry *entry = child->queue_entry;
    if (!entry || !parent->wake_target.entry) return TASK_STEP_YIELD;
    task_queue_lock(&entry->mutex);
    CrustTaskStep step = TASK_STEP_YIELD;
    if (entry->task == child) {
        CrustWakeTicket existing = entry->waiter;
        CrustWakeTicket target = parent->wake_target;
        if (existing.entry && (existing.entry != target.entry || existing.generation != target.generation)) abort();
        entry->waiter = target;
        step = TASK_STEP_PENDING;
    }
    /* If completion detached the entry but has not published worker_done yet,
       Yield bridges that finite publication interval; no notification is lost. */
    task_queue_unlock(&entry->mutex);
    return step;
}
/* A popped entry remains scheduled until the poll has been finalized.
   Wakes in the dequeue-to-poll gap therefore cannot enqueue it twice. */
static CrustQueueEntry *task_queue_pop(CrustReadyQueue *queue, int wait) {
    task_queue_lock(&queue->mutex);
    while (wait && !queue->head && !queue->closed)
        if (pthread_cond_wait(&queue->changed, &queue->mutex)) abort();
    CrustQueueEntry *entry = queue->head;
    if (entry) {
        queue->head = entry->next;
        if (!queue->head) queue->tail = NULL;
        entry->next = NULL;
    }
    task_queue_unlock(&queue->mutex);
    return entry;
}
static int task_queue_run_one(CrustReadyQueue *queue, int wait) {
    CrustQueueEntry *entry = task_queue_pop(queue, wait);
    if (!entry) return 0;
    task_queue_lock(&entry->mutex);
    CrustTask *task = entry->task;
    if (!task || !entry->scheduled) abort();
    task_queue_unlock(&entry->mutex);
    CrustTaskState state;
    if (atomic_load(&task->state) == TASK_QUEUED) {
        task_claim_queued(task);
        state = task_resume_claimed(task);
    } else state = task_poll(task);
    task_queue_lock(&entry->mutex);
    CrustWakeTicket waiter = {0};
    if (state == TASK_COMPLETE) {
        waiter = entry->waiter;
        entry->waiter = (CrustWakeTicket){0};
        entry->task = NULL;
        entry->scheduled = 0;
        task_queue_lock(&queue->mutex);
        if (!queue->outstanding) abort();
        --queue->outstanding;
        task_queue_unlock(&queue->mutex);
    } else if (state == TASK_SUSPENDED) {
        task_scheduling_lock(task);
        int ready = task->ready;
        task_scheduling_unlock(task);
        entry->scheduled = 0;
        if (ready) task_queue_push(queue, entry);
    } else abort();
    task_queue_unlock(&entry->mutex);
    if (state == TASK_COMPLETE) {
        task_queue_wake(waiter);
        /* Completion notification finished. */
        task_queue_lock(&queue->mutex);
        /* Last frame access, after the outgoing notification has returned. */
        atomic_store_explicit(&task->worker_done, 1, memory_order_release);
        if (pthread_cond_broadcast(&queue->changed)) abort();
        task_queue_unlock(&queue->mutex);
    }
    return 1;
}
static void *task_queue_worker(void *pointer) {
    CrustReadyQueue *queue = pointer;
    while (task_queue_run_one(queue, 1)) {}
    return NULL;
}
static int task_queue_close(CrustReadyQueue *queue) {
    task_queue_lock(&queue->mutex);
    int error = queue->outstanding ? EBUSY : 0;
    if (!error) {
        queue->closed = 1;
        if (pthread_cond_broadcast(&queue->changed)) abort();
    }
    task_queue_unlock(&queue->mutex);
    return error;
}
/* Shutdown precondition: workers joined and event producers stopped. */
static void task_queue_entry_destroy(CrustQueueEntry *entry) {
    if (entry->task || entry->scheduled) abort();
    if (pthread_mutex_destroy(&entry->mutex)) abort();
}
static void task_queue_destroy(CrustReadyQueue *queue) {
    if (!queue->closed || queue->outstanding || queue->head) abort();
    if (pthread_cond_destroy(&queue->changed)) abort();
    if (pthread_mutex_destroy(&queue->mutex)) abort();
}

/* The default cooperative scheduler has reusable workers. Blocking requests
   keep their separate launch path; native blocks never pass through this pool. */
static pthread_mutex_t task_default_mutex = PTHREAD_MUTEX_INITIALIZER;
static CrustReadyQueue task_default_queue;
static pthread_t task_default_workers[2];
static int task_default_started;

static int task_default_submit(CrustTask *task) {
    task_queue_lock(&task_default_mutex);
    if (!task_default_started) {
        int error = task_queue_init(&task_default_queue);
        if (error) {
            task_queue_unlock(&task_default_mutex);
            return error;
        }
        unsigned created = 0;
        for (; created < 2; ++created) {
            error = task_pthread_launch(&task_default_workers[created], 0,
                                        task_queue_worker, &task_default_queue);
            if (error) break;
        }
        if (error) {
            if (task_queue_close(&task_default_queue)) abort();
            for (unsigned i = 0; i < created; ++i)
                if (pthread_join(task_default_workers[i], NULL)) abort();
            task_queue_destroy(&task_default_queue);
            task_queue_unlock(&task_default_mutex);
            return error;
        }
        task_default_started = 1;
    }
    CrustWakeTicket ticket;
    int error = task_queue_submit(&task_default_queue, task->queue_entry, task, &ticket);
    task_queue_unlock(&task_default_mutex);
    return error;
}
static void task_default_wait(CrustTask *task) {
    task_queue_lock(&task_default_queue.mutex);
    while (!atomic_load_explicit(&task->worker_done, memory_order_acquire))
        if (pthread_cond_wait(&task_default_queue.changed, &task_default_queue.mutex)) abort();
    task_queue_unlock(&task_default_queue.mutex);
}
static void task_default_close(void) {
    task_queue_lock(&task_default_mutex);
    if (task_default_started) {
        if (task_queue_close(&task_default_queue)) abort();
        for (unsigned i = 0; i < 2; ++i)
            if (pthread_join(task_default_workers[i], NULL)) abort();
        task_queue_destroy(&task_default_queue);
        task_default_started = 0;
    }
    task_queue_unlock(&task_default_mutex);
}

/* MT9: a synchronous guard is thread-affine. The compiler must additionally
   reject holding it across a suspension, even when the next poll uses the
   same thread. These internal operations cannot establish that static rule. */
typedef struct {
    pthread_mutex_t gate;
    void *value;
    void (*destroy_value)(void *);
} CrustSyncMutex;
typedef struct {
    CrustSyncMutex *mutex;
    pthread_t owner;
    void *value;
} CrustSyncGuard;

static int crust_sync_mutex_init(CrustSyncMutex *mutex, void *value,
                                  void (*destroy_value)(void *)) {
    int error = pthread_mutex_init(&mutex->gate, NULL);
    if (error) return error;
    mutex->value = value;
    mutex->destroy_value = destroy_value;
    return 0;
}
static void crust_sync_mutex_lock(CrustSyncMutex *mutex, CrustSyncGuard *guard) {
    if (guard->mutex) abort();
    task_queue_lock(&mutex->gate);
    *guard = (CrustSyncGuard){mutex, pthread_self(), mutex->value};
}
static int crust_sync_guard_drop(CrustSyncGuard *guard) {
    if (!guard->mutex) return EINVAL;
    if (!pthread_equal(guard->owner, pthread_self())) return EPERM;
    CrustSyncMutex *mutex = guard->mutex;
    guard->mutex = NULL;
    guard->value = NULL;
    task_queue_unlock(&mutex->gate);
    return 0;
}
/* Destruction is exclusive: no other call may start or wait concurrently. */
static int crust_sync_mutex_destroy(CrustSyncMutex *mutex) {
    int error = pthread_mutex_trylock(&mutex->gate);
    if (error) return error;
    if (mutex->destroy_value) mutex->destroy_value(mutex->value);
    mutex->value = NULL;
    task_queue_unlock(&mutex->gate);
    return pthread_mutex_destroy(&mutex->gate);
}

typedef struct CrustAsyncMutex CrustAsyncMutex;
typedef struct CrustMutexWait CrustMutexWait;
typedef enum {
    CRUST_MUTEX_IDLE, CRUST_MUTEX_WAITING, CRUST_MUTEX_RESERVED,
    CRUST_MUTEX_TAKEN, CRUST_MUTEX_DISCARDED
} CrustMutexWaitState;
struct CrustMutexWait {
    CrustAsyncMutex *mutex;
    CrustMutexWait *previous, *next;
    CrustWakeTicket wake;
    CrustMutexWaitState state;
};
struct CrustAsyncMutex {
    pthread_mutex_t gate; /* Short bookkeeping only; never held over a poll. */
    void *value;
    void (*destroy_value)(void *);
    int locked;
    CrustMutexWait *head, *tail, *reservation;
};
typedef struct {
    CrustAsyncMutex *mutex;
    void *value;
} CrustAsyncGuard;

static int crust_async_mutex_init(CrustAsyncMutex *mutex, void *value,
                                   void (*destroy_value)(void *)) {
    int error = pthread_mutex_init(&mutex->gate, NULL);
    if (error) return error;
    mutex->value = value;
    mutex->destroy_value = destroy_value;
    mutex->locked = 0;
    mutex->head = mutex->tail = mutex->reservation = NULL;
    return 0;
}
static void crust_mutex_wait_init(CrustMutexWait *wait) {
    *wait = (CrustMutexWait){0};
}
/* All list and reservation operations hold mutex->gate. Wait nodes stay in
   pinned frames until removed. Notifications use stable generation tickets,
   never a wait node or frame pointer after releasing the gate. */
static void crust_mutex_unlink(CrustAsyncMutex *mutex, CrustMutexWait *wait) {
    if (wait->previous) wait->previous->next = wait->next;
    else mutex->head = wait->next;
    if (wait->next) wait->next->previous = wait->previous;
    else mutex->tail = wait->previous;
    wait->previous = wait->next = NULL;
}
static CrustWakeTicket crust_mutex_handoff(CrustAsyncMutex *mutex) {
    mutex->reservation = NULL;
    CrustMutexWait *next = mutex->head;
    if (!next) {
        mutex->locked = 0;
        return (CrustWakeTicket){0};
    }
    crust_mutex_unlink(mutex, next);
    next->state = CRUST_MUTEX_RESERVED;
    mutex->reservation = next;
    /* Keep locked: another arrival cannot steal this reservation. */
    return next->wake;
}
static CrustTaskStep crust_async_mutex_poll(CrustAsyncMutex *mutex,
        CrustMutexWait *wait, CrustTask *task, CrustAsyncGuard *guard) {
    if (guard->mutex) abort();
    task_queue_lock(&mutex->gate);
    if (wait->state == CRUST_MUTEX_IDLE) {
        wait->mutex = mutex;
        wait->wake = task->wake_target;
        if (!mutex->locked) {
            mutex->locked = 1;
            wait->state = CRUST_MUTEX_RESERVED;
            mutex->reservation = wait;
        } else {
            wait->state = CRUST_MUTEX_WAITING;
            wait->previous = mutex->tail;
            if (mutex->tail) mutex->tail->next = wait;
            else mutex->head = wait;
            mutex->tail = wait;
        }
    }
    if (wait->mutex != mutex || (wait->state != CRUST_MUTEX_WAITING
                                && wait->state != CRUST_MUTEX_RESERVED)) abort();
    CrustTaskStep step;
    if (wait->state == CRUST_MUTEX_RESERVED) {
        if (mutex->reservation != wait) abort();
        mutex->reservation = NULL;
        wait->state = CRUST_MUTEX_TAKEN;
        wait->mutex = NULL; /* The guard now owns the only lifetime obligation. */
        *guard = (CrustAsyncGuard){mutex, mutex->value};
        step = TASK_STEP_RETURN;
    } else {
        /* Bare unscheduled probes have no ticket. Scheduled executions park
           and rely on handoff waking their root poll (including direct await). */
        wait->wake = task->wake_target;
        step = wait->wake.entry ? TASK_STEP_PENDING : TASK_STEP_YIELD;
    }
    task_queue_unlock(&mutex->gate);
    return step;
}
static int crust_async_guard_drop(CrustAsyncGuard *guard) {
    CrustAsyncMutex *mutex = guard->mutex;
    if (!mutex) return EINVAL;
    task_queue_lock(&mutex->gate);
    if (!mutex->locked || mutex->reservation) abort();
    guard->mutex = NULL;
    guard->value = NULL;
    CrustWakeTicket wake = crust_mutex_handoff(mutex);
    task_queue_unlock(&mutex->gate);
    task_queue_wake(wake);
    return 0;
}
/* SL1: discard removes an unacquired wait, or passes on its reservation.
   Once acquired, only the guard owns the lock; discarding the wait cannot
   release it. The state destructor must drop that guard separately. */
static void crust_mutex_wait_discard(CrustMutexWait *wait) {
    CrustAsyncMutex *mutex = wait->mutex;
    if (!mutex) {
        wait->state = CRUST_MUTEX_DISCARDED;
        return;
    }
    task_queue_lock(&mutex->gate);
    CrustWakeTicket wake = {0};
    if (wait->state == CRUST_MUTEX_WAITING) crust_mutex_unlink(mutex, wait);
    else if (wait->state == CRUST_MUTEX_RESERVED) {
        if (mutex->reservation != wait) abort();
        wake = crust_mutex_handoff(mutex);
    }
    wait->mutex = NULL;
    wait->state = CRUST_MUTEX_DISCARDED;
    task_queue_unlock(&mutex->gate);
    task_queue_wake(wake);
}
static int crust_async_mutex_destroy(CrustAsyncMutex *mutex) {
    task_queue_lock(&mutex->gate);
    if (mutex->locked || mutex->head || mutex->reservation) {
        task_queue_unlock(&mutex->gate);
        return EBUSY;
    }
    if (mutex->destroy_value) mutex->destroy_value(mutex->value);
    mutex->value = NULL;
    task_queue_unlock(&mutex->gate);
    return pthread_mutex_destroy(&mutex->gate);
}

/* The worker only accesses its own stable task slot. It publishes
   completion as its last access, so the parent handle can disappear. */
typedef struct {
    CrustTask *task;
    int error;
} CrustAsyncExecution;

/* Transfer the wait obligation to a synchronous ABI without waiting or
   submitting the task again. Async-native workers are already detached;
   all workers publish worker_done through the shared completion protocol. */
static void task_sync_adopt(CrustExecution *target, CrustAsyncExecution *source) {
    *target = (CrustExecution){0};
    target->task = source->task;
    target->error = source->error;
    target->pooled = 1;
    atomic_init(&target->joined, 0);
    source->task = NULL;
    source->error = 0;
}

/* Consume a synchronous handle without waiting for its worker. The worker
   publishes completion through the task slot, so the async waiter uses the
   same notification protocol as a handle created directly in an async body. */
static void task_async_adopt(CrustAsyncExecution *target, CrustExecution *source) {
    if (atomic_exchange(&source->joined, 1)) abort();
    if (!source->error && !source->pooled &&
            (!source->detach || source->detach(source->thread))) abort();
    target->task = source->task;
    target->error = source->error;
    source->task = NULL;
    source->error = 0;
}

static void task_start_detached(CrustAsyncExecution *execution, CrustTask *task,
        int (*launch)(pthread_t *, int, void *(*)(void *), void *), void *(*run)(void *)) {
    CrustTaskState inactive = TASK_INACTIVE;
    if (!atomic_compare_exchange_strong(&task->state, &inactive, TASK_QUEUED)) abort();
    execution->task = task;
    pthread_t thread;
    int error = task_external_register(task);
    if (!error) error = launch ? launch(&thread, 1, run, task) : ENOTSUP;
    execution->error = error;
    if (error) {
        task_external_forget(task);
        atomic_store(&task->state, TASK_INACTIVE);
        if (!task_drop_inactive(task)) abort();
        execution->task = NULL;
    }
}

static void task_async_start_mode(CrustAsyncExecution *execution, CrustTask *task,
                                  const CrustThreadScheduler *scheduler, int blocking) {
    if (scheduler == &task_default_scheduler && !blocking && task->queue_entry) {
        execution->task = task;
        int error = task_default_submit(task);
        execution->error = error;
        if (error) {
            if (!task_drop_inactive(task)) abort();
            execution->task = NULL;
        }
        return;
    }
    task_start_detached(execution, task,
        blocking ? scheduler->launch_blocking : scheduler->launch, task_thread_run);
}

static void task_native_async_start(CrustAsyncExecution *execution, CrustTask *task) {
    task_start_detached(execution, task, task_pthread_launch, task_native_run);
}

static void task_async_start_with(CrustAsyncExecution *execution, CrustTask *task,
                                  const CrustThreadScheduler *scheduler) {
    task_async_start_mode(execution, task, scheduler, 0);
}

static void task_async_start_blocking_with(CrustAsyncExecution *execution, CrustTask *task,
                                         const CrustThreadScheduler *scheduler) {
    task_async_start_mode(execution, task, scheduler, 1);
}

